package com.readwide.manager.archive;
import org.junit.*;import org.junit.rules.TemporaryFolder;
import java.io.*;import java.nio.file.*;import java.util.*;
import static org.junit.Assert.*;

public class AlzEggVolumeRound4Test {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 private List<File> alz(int count)throws Exception{return Round4Fixtures.splitAlz(temp.newFolder(),"book",Round4Fixtures.alz(Round4Fixtures.data(6011),0,false),count);}
 private List<File> egg(int count)throws Exception{return Round4Fixtures.splitEgg(temp.newFolder(),"book",Round4Fixtures.egg(Round4Fixtures.data(6023),0,false),count);}
 @Test public void alzLaterSelectionHasSameOrderedCatalogue()throws Exception{List<File> f=alz(3);assertEquals(f,AlzVolumeResolver.resolve(f.get(2)).files);assertEquals(f.get(0),AlzVolumeResolver.resolveFirstVolume(f.get(1)));}
 @Test public void alzWideContinuationSupports1003RealStoredParts()throws Exception{List<File> f=alz(1003);File out=temp.newFile();assertEquals(1003,AlzVolumeResolver.resolve(f.get(1002)).files.size());assertTrue(AlzipArchiveReader.extractSingleEntry(f.get(1002),"data.bin",out,null));assertArrayEquals(Round4Fixtures.data(6011),Files.readAllBytes(out.toPath()));}
 @Test public void alzMixedCaseFirstPartResolves()throws Exception{List<File> f=alz(2);File upper=new File(f.get(0).getParentFile(),"BOOK.ALZ");Files.move(f.get(0).toPath(),upper.toPath());assertEquals(upper,AlzVolumeResolver.resolveFirstVolume(f.get(1)));assertEquals(ArchiveSupport.Type.ALZ,ArchiveTypeDetector.fromFile(f.get(1)));}
 @Test public void alzMissingDeclaredTailRejected()throws Exception{List<File>f=alz(2);Files.delete(f.get(1).toPath());assertThrows(IOException.class,()->AlzVolumeResolver.resolve(f.get(0)));}
 @Test public void alzGapRejected()throws Exception{List<File>f=alz(3);Files.delete(f.get(1).toPath());assertThrows(IOException.class,()->AlzVolumeResolver.resolve(f.get(0)));}
 @Test public void alzAliasRejected()throws Exception{List<File>f=alz(2);Files.copy(f.get(1).toPath(),new File(f.get(1).getParentFile(),"book.a000").toPath());assertThrows(IOException.class,()->AlzVolumeResolver.resolve(f.get(0)));}
 @Test public void alzDirectoryMasqueradeRejected()throws Exception{List<File>f=alz(2);Files.delete(f.get(1).toPath());Files.createDirectory(f.get(1).toPath());assertThrows(IOException.class,()->AlzVolumeResolver.resolve(f.get(0)));}
 @Test public void alzBadTrailerRejected()throws Exception{List<File>f=alz(2);try(RandomAccessFile out=new RandomAccessFile(f.get(1),"rw")){out.seek(out.length()-1);out.write(99);}assertThrows(IOException.class,()->AlzVolumeResolver.resolve(f.get(0)));}
 @Test public void alzEarlyEndMarkerRejected()throws Exception{List<File>f=alz(3);try(RandomAccessFile out=new RandomAccessFile(f.get(1),"rw")){out.seek(out.length()-1);out.write(2);}assertThrows(IOException.class,()->AlzVolumeResolver.resolve(f.get(0)));}
 @Test public void alzOverflowOrdinalRejectedWithoutNumericProbing()throws Exception{List<File>f=alz(2);File huge=Round4Fixtures.write(f.get(0).getParentFile(),"book.a99999999999999999999999",new byte[]{1});assertThrows(IOException.class,()->AlzVolumeResolver.resolve(huge));}
 @Test public void alzLegacyRawContinuationRemainsReadable()throws Exception{List<File>f=alz(2);byte[] b=Files.readAllBytes(f.get(1).toPath());Files.write(f.get(1).toPath(),Arrays.copyOfRange(b,8,b.length-16));File out=temp.newFile();assertTrue(AlzipArchiveReader.extractSingleEntry(f.get(1),"data.bin",out,null));assertArrayEquals(Round4Fixtures.data(6011),Files.readAllBytes(out.toPath()));}
 @Test public void alzSnapshotIncludesContinuation()throws Exception{List<File>f=alz(2);ArchiveSourceSnapshot a=ArchiveSourceSnapshot.capture(f.get(0));assertTrue(a.matches(f.get(0)));assertEquals(a.cacheFingerprint(),ArchiveSourceSnapshot.capture(f.get(1)).cacheFingerprint());assertTrue(f.get(1).setLastModified(f.get(1).lastModified()+10000));assertFalse(a.matches(f.get(0)));}
 @Test public void alzMissingTailCannotReuseCache()throws Exception{List<File>f=alz(2);ArchiveSourceSnapshot a=ArchiveSourceSnapshot.capture(f.get(0));Files.delete(f.get(1).toPath());ArchiveSourceSnapshot bad=ArchiveSourceSnapshot.capture(f.get(0));assertFalse(bad.matches(f.get(0)));assertNotEquals(a.cacheFingerprint(),bad.cacheFingerprint());}
 @Test public void alzOutputNameOmitsContinuationSuffix(){assertEquals("book",ArchiveTypeDetector.outputBaseName(new File("book.a1000"),"fallback"));}
 @Test public void eggLaterSelectionHasSameChain()throws Exception{List<File>f=egg(3);assertEquals(f,EggVolumeResolver.resolve(f.get(2)).files);assertEquals(f.get(0),EggVolumeResolver.resolveFirstVolume(f.get(2)));}
 @Test public void egg1005RealStoredPartsDecode()throws Exception{List<File>f=egg(1005);File out=temp.newFile();assertEquals(1005,EggVolumeResolver.resolve(f.get(1004)).files.size());assertTrue(EggArchiveReader.extractSingleEntry(f.get(1004),"data.bin",out,null));assertArrayEquals(Round4Fixtures.data(6023),Files.readAllBytes(out.toPath()));}
 @Test public void eggMixedCaseAndPaddedOrdinalsResolve()throws Exception{List<File>f=egg(2);File first=new File(f.get(0).getParentFile(),"BOOK.VOL01.EGG"),second=new File(f.get(0).getParentFile(),"BoOk.VoL02.EgG");Files.move(f.get(0).toPath(),first.toPath());Files.move(f.get(1).toPath(),second.toPath());assertEquals(Arrays.asList(first,second),EggVolumeResolver.resolve(second).files);}
 @Test public void eggMissingRequiredTailRejected()throws Exception{List<File>f=egg(2);Files.delete(f.get(1).toPath());assertThrows(IOException.class,()->EggVolumeResolver.resolve(f.get(0)));}
 @Test public void eggPrevIdMismatchRejected()throws Exception{List<File>f=egg(2);try(RandomAccessFile out=new RandomAccessFile(f.get(1),"rw")){out.seek(21);out.write(0);}assertThrows(IOException.class,()->EggVolumeResolver.resolve(f.get(0)));}
 @Test public void eggNextIdMismatchRejected()throws Exception{List<File>f=egg(2);try(RandomAccessFile out=new RandomAccessFile(f.get(0),"rw")){out.seek(25);out.write(0);}assertThrows(IOException.class,()->EggVolumeResolver.resolve(f.get(0)));}
 @Test public void eggAliasRejected()throws Exception{List<File>f=egg(2);Files.copy(f.get(1).toPath(),new File(f.get(0).getParentFile(),"book.vol02.egg").toPath());assertThrows(IOException.class,()->EggVolumeResolver.resolve(f.get(0)));}
 @Test public void eggDirectoryMasqueradeRejected()throws Exception{List<File>f=egg(2);Files.delete(f.get(1).toPath());Files.createDirectory(f.get(1).toPath());assertThrows(IOException.class,()->EggVolumeResolver.resolve(f.get(0)));}
 @Test public void eggOrphanLaterSelectionCannotOpenDifferentArchive()throws Exception{List<File>f=egg(2);byte[] first=Files.readAllBytes(f.get(0).toPath());Arrays.fill(first,25,29,(byte)0);Files.write(f.get(0).toPath(),first);assertThrows(IOException.class,()->EggVolumeResolver.resolve(f.get(1)));}
 @Test public void eggDuplicateSplitFieldRejected()throws Exception{File dir=temp.newFolder();byte[] prefix=Round4Fixtures.prefix(1,0,0,true);ByteArrayOutputStream bytes=new ByteArrayOutputStream();bytes.write(prefix,0,29);bytes.write(prefix,14,15);bytes.write(prefix,29,4);File file=Round4Fixtures.write(dir,"book.egg",bytes.toByteArray());assertThrows(IOException.class,()->EggVolumeResolver.resolve(file));}
 @Test public void eggOversizedExtraFieldRejected()throws Exception{byte[] b=Round4Fixtures.prefix(1,0,0,true);b[19]=(byte)255;b[20]=(byte)255;File f=Round4Fixtures.write(temp.newFolder(),"book.egg",b);assertThrows(IOException.class,()->EggVolumeResolver.resolve(f));}
 @Test public void eggSnapshotIncludesContinuation()throws Exception{List<File>f=egg(2);ArchiveSourceSnapshot a=ArchiveSourceSnapshot.capture(f.get(0));assertTrue(a.matches(f.get(0)));assertEquals(a.cacheFingerprint(),ArchiveSourceSnapshot.capture(f.get(1)).cacheFingerprint());assertTrue(f.get(1).setLastModified(f.get(1).lastModified()+10000));assertFalse(a.matches(f.get(0)));}
 @Test public void eggMissingTailCannotReuseCache()throws Exception{List<File>f=egg(2);ArchiveSourceSnapshot a=ArchiveSourceSnapshot.capture(f.get(0));Files.delete(f.get(1).toPath());assertFalse(a.matches(f.get(0)));assertFalse(ArchiveSourceSnapshot.capture(f.get(0)).matches(f.get(0)));}
 @Test public void eggOutputNameOmitsVolumeSuffix(){assertEquals("book",ArchiveTypeDetector.outputBaseName(new File("book.vol1001.egg"),"fallback"));}
 @Test public void cancelledResolversPreserveInterrupt()throws Exception{List<File>a=alz(2),e=egg(2);try{Thread.currentThread().interrupt();assertThrows(InterruptedIOException.class,()->AlzVolumeResolver.resolve(a.get(0)));assertThrows(InterruptedIOException.class,()->EggVolumeResolver.resolve(e.get(0)));assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();}}
 @Test public void malformedHeadersAreRejectedNotCached()throws Exception{for(String name:new String[]{"book.egg","book.alz"}){File f=Round4Fixtures.write(temp.newFolder(),name,new byte[]{1,2,3});if(name.endsWith("egg"))assertThrows(IOException.class,()->EggVolumeResolver.resolve(f));else assertThrows(IOException.class,()->AlzipArchiveReader.listEntries(f,null));}}
}
